# No imports. Entry point verify(witness). Raises AssertionError on any failure.

def is_intersecting_allpairs(fam):
    # Mathlib Set.Intersecting: all pairs incl. A=B => no empty set, pairwise intersect.
    lst = list(fam)
    for a in lst:
        if a == 0:
            return False
    for i in range(len(lst)):
        for j in range(i, len(lst)):
            if (lst[i] & lst[j]) == 0:
                return False
    return True

def is_hereditary(fam, n):
    for a in fam:
        for e in range(n):
            if (a >> e) & 1:
                if (a ^ (1 << e)) not in fam:
                    return False
    return True

def subsets_all(n):
    return list(range(1 << n))

def combos(items, r):
    # itertools-free combinations by index recursion (exact, deterministic)
    res = []
    k = len(items)
    def rec(start, cur):
        if len(cur) == r:
            res.append(tuple(cur))
            return
        for i in range(start, k):
            cur.append(items[i])
            rec(i + 1, cur)
            cur.pop()
    rec(0, [])
    return res

def verify(witness):
    assert witness['n_small'] == 3
    assert witness['n_full'] == 4

    # Part 1: every hereditary family on [3]: every pairwise-intersecting
    # subfamily has size <= 4; star achieves 4.
    n3 = 3
    S3 = subsets_all(n3)
    half3 = 1 << (n3 - 1)
    for c in combos(S3, 0) + combos(S3,1) + combos(S3,2) + combos(S3,3) + \
             combos(S3,4) + combos(S3,5) + combos(S3,6) + combos(S3,7) + combos(S3,8):
        F = set(c)
        if not is_hereditary(F, n3):
            continue
        for r2 in range(len(F) + 1):
            for c2 in combos(sorted(F), r2):
                sub = set(c2)
                if is_intersecting_allpairs(sub):
                    assert len(sub) <= half3, 'hereditary [3] bound violated'
    star3 = frozenset(a for a in S3 if (a & 1) == 1)
    assert is_intersecting_allpairs(star3) and len(star3) == half3

    # Part 2: n = 4, exhaustive over all 2^16 candidate families:
    # pairwise-intersecting (all-pairs, no empty set) => size <= 8;
    # at most one member per complement pair; star achieves 8.
    n4 = 4
    S4 = subsets_all(n4)
    half4 = 1 << (n4 - 1)
    for mask in range(1 << len(S4)):
        fam = [S4[i] for i in range(len(S4)) if (mask >> i) & 1]
        if not is_intersecting_allpairs(set(fam)):
            continue
        assert len(fam) <= half4, 'n=4 intersecting bound violated'
        seen_complements = set()
        for a in fam:
            comp = (~a) & (15)
            assert a not in seen_complements, 'complement-pair rule violated'
            seen_complements.add(comp)
    star4 = frozenset(a for a in S4 if (a & 1) == 1)
    assert is_intersecting_allpairs(star4) and len(star4) == half4
    return True
